            break;
        case EvolWrapperErrorInfo::SideClampSource:
            errorSourceText = "SideClampSource";
            break;
        case EvolWrapperErrorInfo::SideFolderSource:
            errorSourceText = "SideFolderSource";
            break;
        case EvolWrapperErrorInfo::RearFolderSource:
            errorSourceText = "RearFolderSource";
            break;
