void EvolWrapperErrorInfo::operator=(const EvolWrapperErrorInfo& ewei)
{
    primaryConveyor = ewei.getPrimaryConveyor();
    secondaryConveyor = ewei.getSecondaryConveyor();
    secondaryShift = ewei.getSecondaryShift();
    elevator = ewei.getElevator();
    filmSupply = ewei.getFilmSupply();
    gripper = ewei.getGripper();
    knife = ewei.getKnife();
    sideClamp = ewei.getSideClamp();
    sideFolder = ewei.getSideFolder();
    rearFolder = ewei.getRearFolder();
    frontFolder = ewei.getFrontFolder();
    pusher = ewei.getPusher();
    sealerBelt = ewei.getSealerBelt();
    labelApplier = ewei.getLabelApplier();
    generalWrapper = ewei.getGeneralWrapper();
    diagnosticsSupport = ewei.getDiagnosticsSupport();
}
bool EvolWrapperErrorInfo::operator == (const EvolWrapperErrorInfo& ewti) const
{
	return equals(ewti);
}

bool EvolWrapperErrorInfo::operator != (const EvolWrapperErrorInfo& ewti) const
{
	return !equals(ewti);
}
